(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zzu-sj-prepa-med-j9-idesfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zzu-sj-prepa-med-j9-idesfm\",\n \"titre\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 49,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n   \"sha256\": \"3be3f44293a1050566934462ec0ef192757b5dc283cfd03ed3cc2d585a095ef9\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Médecine · Prépa D.E J9 (IDE-SF-M)\",\n     \"slug\": \"prepa-med-j9-idesfm\",\n     \"pages\": \"\",\n     \"count\": 49,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Médecine\",\n     \"source\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__0\",\n       \"num\": \"1\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Tous ces composants font partie des organes annexes de l'appareil digestif sauf deux, lesquels :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les glandes salivaires\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La vésicule biliaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le foie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'estomac\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le pancréas\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"L'œsophage\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"F. L'œsophage\",\n       \"answerLetters\": [\n        \"F\"\n       ],\n       \"explanation\": \"Les glandes annexes du tube digestif sont les glandes salivaires, le foie (avec la vésicule biliaire) et le pancréas. L'œsophage et l'estomac appartiennent au tube digestif lui-même. Remarque : L'énoncé demande deux réponses, mais la question est à choix unique et seule « L'œsophage » est validée. L'estomac fait lui aussi partie du tube digestif (et non des annexes).\\n\\nSource : (explication hors cours du projet : anatomie)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__1\",\n       \"num\": \"2\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans l'angiocholite aiguë, deux signes cliniques sont exacts\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Constipation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Douleur\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Fièvre élevée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Diarrhée rare\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Douleur ; C. Fièvre élevée\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"L'angiocholite aiguë (obstruction de la voie biliaire principale, souvent par lithiase) associe une triade qui s'installe en 24 à 72 h : douleur de l'hypochondre droit, fièvre élevée avec frissons, puis ictère.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Lithiase biliaire – Angiocholite aiguë\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__2\",\n       \"num\": \"3\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'occlusion intestinale présente deux mécanismes\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"b. Hémorragie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"d. Occlusion fonctionnelle\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"a. Occlusion organique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"c. Douleur biliaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. d. Occlusion fonctionnelle ; C. a. Occlusion organique\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"On distingue l'occlusion organique (obstacle mécanique : bride, volvulus, tumeur, étranglement) et l'occlusion fonctionnelle (paralysie intestinale sans obstacle : iléus réflexe).\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__3\",\n       \"num\": \"4\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les complications de l'ulcère gastro-duodénal sont les suivantes sauf une, laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"c. Hémorragie digestive\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Perforation digestive\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"d. Sténose duodénale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"a. La cancérisation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. a. La cancérisation\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le cours cite quatre complications de l'UGD : hémorragie digestive (la plus fréquente), perforation, sténose et transformation cancéreuse (risque faible, ulcère gastrique seulement).\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Ulcère gastro-duodénal, § IV Complications\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__4\",\n       \"num\": \"5\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel diagnostic évoquer devant le tableau clinique suivant : rejet brutal et massif d'une grande quantité de pus ou de liquide clair à la faveur d'un effort de toux ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Expectoration\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Vomique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Hémoptysie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Toux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Vomique\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La vomique est le rejet brutal, par la bouche, au cours d'un effort de toux, d'une grande quantité de pus ou de liquide (ouverture d'un abcès ou d'un kyste dans les bronches). Hémoptysie = sang ; expectoration = crachat banal.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Tuberculose et suppurations pulmonaires (vomique)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__5\",\n       \"num\": \"6\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les complications suivantes de l'UGD, il existe un intrus : lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hémorragie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ostéoporose\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Perforation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Ostéoporose\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Hémorragie et perforation sont des complications de l'UGD ; l'ostéoporose n'en est pas une.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Ulcère gastro-duodénal, § IV Complications\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__6\",\n       \"num\": \"7\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'appareil digestif est composé de deux grandes parties, lesquelles :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les glandes annexes du digestif\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La bouche\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le tube digestif\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les glandes salivaires\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Les glandes annexes du digestif ; C. Le tube digestif\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"L'appareil digestif comprend le tube digestif (bouche → anus) et les glandes annexes (salivaires, foie, pancréas). La bouche et les glandes salivaires sont des éléments de ces deux parties.\\n\\nSource : (explication hors cours du projet : anatomie)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__7\",\n       \"num\": \"8\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le côlon fait partie :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Du tube digestif\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"De la partie haute du tube digestif\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"De la partie basse du tube digestif\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Des annexes de l'appareil digestif\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Du tube digestif ; C. De la partie basse du tube digestif\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Le côlon (gros intestin) fait partie du tube digestif, dans sa partie basse (après l'intestin grêle). Ce n'est pas une glande annexe.\\n\\nSource : (explication hors cours du projet : anatomie)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__8\",\n       \"num\": \"9\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les complications de la néphropathie gravidique sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"c. Épilepsie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"a. La mort fœtale in utero\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"b. L'hématome rétroplacentaire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Éclampsie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. a. La mort fœtale in utero ; D. Éclampsie\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"La néphropathie gravidique vraie (toxémie) peut se compliquer d'éclampsie (accidents convulsifs) et de mort fœtale. Remarque : L'hématome rétroplacentaire est aussi une complication classique de la pré-éclampsie (cours de gynéco-obstétrique), mais il n'est pas retenu dans la correction nationale de la Prépa DE (les J).\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Néphropathie gravidique vraie\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__9\",\n       \"num\": \"10\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les ulcères gastro-duodénaux, le(s) siège(s) de la sténose est (sont) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le duodénum\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"c. Le pylore\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"b. Le cardia\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Le duodénum ; B. c. Le pylore\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"La sténose ulcéreuse complique les ulcères bulbaires (duodénaux) et pré-pyloriques : duodénum et pylore.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Ulcère gastro-duodénal, § IV-3 Sténose ulcéreuse\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__10\",\n       \"num\": \"11\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'examen complémentaire essentiel dans le diagnostic des gastrites est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"c. Fibroscopie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"a. Tubage gastrique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"b. Radiologie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. c. Fibroscopie\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La fibroscopie (endoscopie œso-gastro-duodénale avec biopsies) est l'examen de référence pour le diagnostic des gastrites (la gastrite est une définition histologique).\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Ulcère gastro-duodénal et gastrite ; Documents de révision L3 Médecine, Appareil digestif QCM 6\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__11\",\n       \"num\": \"12\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ponction d'ascite est l'évacuation des épanchements contenus en abondance dans :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"c. La cavité péritonéale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"a. La cavité pleurale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"b. La cavité pancréatique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. c. La cavité péritonéale\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La ponction d'ascite (paracentèse) évacue le liquide accumulé dans la cavité péritonéale.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Soins infirmiers dans la ponction d'ascite\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__12\",\n       \"num\": \"13\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ponction d'ascite se fait dans :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La fosse iliaque droite\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'hypochondre droit\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"d. L'hypochondre gauche\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"c. La fosse iliaque gauche\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. c. La fosse iliaque gauche\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"« La ponction se fait dans la fosse iliaque gauche pour éviter une blessure du foie ou du cœur. » Remarque : Dans le sujet, l'énoncé commence par « a. La cavité péritonéale », reste de la question précédente.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Ponction d'ascite, § V Technique\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__13\",\n       \"num\": \"14\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La cirrhose est une pathologie du :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Cœur\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rate\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Foie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Foie\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La cirrhose est une maladie chronique du foie (principale cause d'insuffisance hépatique chronique).\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Les cirrhoses\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__14\",\n       \"num\": \"15\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Choisir les deux bonnes réponses : l'hypophyse est formée de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"lobe antérieur\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"lobe supérieur\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"lobe postérieur\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"lobe en amont\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"lobe inférieur\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. lobe antérieur ; C. lobe postérieur\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"L'hypophyse comprend un lobe antérieur (antéhypophyse, glandulaire) et un lobe postérieur (posthypophyse, nerveuse).\\n\\nSource : (explication hors cours du projet : anatomie)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les complications de l'ulcère gastroduodénal sont les suivantes\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"hémorragie digestive\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"perforation gastrique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"rétention aiguë d'urine\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"sténose\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. hémorragie digestive ; B. perforation gastrique ; D. sténose\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Complications de l'UGD : hémorragie digestive, perforation, sténose (et transformation cancéreuse). La rétention aiguë d'urine n'en fait pas partie.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Ulcère gastro-duodénal, § IV Complications\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Reliez les complications aux pathologies correspondantes. Complications : aDermite… ; b- Embolie pulmonaire ; c- Dermatose. Maladies : 1- Thrombose veineuse profonde des membres inférieurs ; 2- Varices des membres inférieurs ; 3- Œdème aigu des poumons.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(b-3)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(b-1)\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(b-2)\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"(a-1)\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"(a-2)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. (b-1) ; E. (a-2)\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"L'embolie pulmonaire est la complication immédiate de la thrombose veineuse profonde (b-1) ; la dermite (ocre) est une complication cutanée des varices des membres inférieurs (a-2).\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Phlébite (« embolie pulmonaire dans 80 % des cas ») (explication partiellement hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__17\",\n       \"num\": \"18\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Cas pratique : Vous êtes en service au CSU d'Aniassué et vous recevez Mlle Motiky, âgée de 32 ans, caissière dans une banque, pour céphalées, fièvre, vertiges, diarrhée, anorexie, insomnie depuis deux jours. À l'examen vous notez : T° 40 °C, pouls 70 puls/min, TA 120/70 mmHg, poids 90 kg, taille 1,70 m.\",\n       \"text\": \"Quelle est votre hypothèse diagnostique ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Paludisme\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Fièvre typhoïde\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Méningite\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Fièvre typhoïde\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Fièvre à 40 °C avec pouls à 70 (dissociation pouls-température), céphalées, insomnie, vertiges, diarrhée : tableau de fièvre typhoïde.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Fièvre typhoïde, § 2.2 et 2.3\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__18\",\n       \"num\": \"19\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Cas pratique : Vous êtes en service au CSU d'Aniassué et vous recevez Mlle Motiky, âgée de 32 ans, caissière dans une banque, pour céphalées, fièvre, vertiges, diarrhée, anorexie, insomnie depuis deux jours. À l'examen vous notez : T° 40 °C, pouls 70 puls/min, TA 120/70 mmHg, poids 90 kg, taille 1,70 m.\",\n       \"text\": \"Cochez parmi les éléments ci-dessous les trois qui justifient votre hypothèse diagnostique\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Céphalées\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Diarrhée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pouls 70 puls/min\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"T° 40 °C\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Vomissement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Céphalées ; C. Pouls 70 puls/min ; D. T° 40 °C\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Céphalées (CIVET), fièvre à 40 °C et pouls à 70/min (dissociation pouls-température) orientent vers la typhoïde. Diarrhée et vomissements sont moins spécifiques.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Fièvre typhoïde, § 2.2 et 2.3\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__19\",\n       \"num\": \"20\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Cas pratique : Vous êtes en service au CSU d'Aniassué et vous recevez Mlle Motiky, âgée de 32 ans, caissière dans une banque, pour céphalées, fièvre, vertiges, diarrhée, anorexie, insomnie depuis deux jours. À l'examen vous notez : T° 40 °C, pouls 70 puls/min, TA 120/70 mmHg, poids 90 kg, taille 1,70 m.\",\n       \"text\": \"Quel est le germe responsable de cette maladie ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Méningocoque\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Salmonelle\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Plasmodium\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Staphylocoque\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Salmonelle\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La fièvre typhoïde est due à Salmonella typhi (et paratyphi A, B, C).\\n\\nSource : Cours de maladies infectieuses et parasitaires, Fièvre typhoïde, § 2a\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__20\",\n       \"num\": \"21\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Cas pratique : Vous êtes en service au CSU d'Aniassué et vous recevez Mlle Motiky, âgée de 32 ans, caissière dans une banque, pour céphalées, fièvre, vertiges, diarrhée, anorexie, insomnie depuis deux jours. À l'examen vous notez : T° 40 °C, pouls 70 puls/min, TA 120/70 mmHg, poids 90 kg, taille 1,70 m.\",\n       \"text\": \"Quel est l'examen biologique qui peut aider à poser le diagnostic ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"PL\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Goutte épaisse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Coproculture\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"NFS\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Coproculture\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La coproculture permet le diagnostic en période de diarrhée (mise en évidence de la salmonelle dans les selles). Remarque : L'examen de certitude cité par le cours est l'hémoculture (positive dans les 2 premières semaines), mais elle ne figure pas parmi les propositions. Par ailleurs, vous constatez qu'elle tousse ; à l'interrogatoire, elle affirme que cette toux évolue depuis un (01) mois avec une anorexie et une asthénie. La radiographie pulmonaire montre des cavitations, l'examen de crachat est positif au BK, la sérologie VIH est négative.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Fièvre typhoïde, § III Biologie\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__21\",\n       \"num\": \"22\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Cas pratique : Vous êtes en service au CSU d'Aniassué et vous recevez Mlle Motiky, âgée de 32 ans, caissière dans une banque, pour céphalées, fièvre, vertiges, diarrhée, anorexie, insomnie depuis deux jours. À l'examen vous notez : T° 40 °C, pouls 70 puls/min, TA 120/70 mmHg, poids 90 kg, taille 1,70 m.\",\n       \"text\": \"De quelle autre pathologie souffre Mlle Motiky ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Tuberculose osseuse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Miliaire tuberculeuse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Tuberculose pulmonaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Tuberculose pulmonaire\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Toux depuis un mois, anorexie, asthénie, cavitations radiologiques et crachats BK positifs : tuberculose pulmonaire.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Tuberculose (localisation principale : le poumon)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__22\",\n       \"num\": \"23\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Cas pratique : Vous êtes en service au CSU d'Aniassué et vous recevez Mlle Motiky, âgée de 32 ans, caissière dans une banque, pour céphalées, fièvre, vertiges, diarrhée, anorexie, insomnie depuis deux jours. À l'examen vous notez : T° 40 °C, pouls 70 puls/min, TA 120/70 mmHg, poids 90 kg, taille 1,70 m.\",\n       \"text\": \"Quel est le protocole adapté à cette maladie ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rifampicine, Isoniazide, Éthambutol, Pyrazinamide pendant 2 mois et Rifampicine et Isoniazide pendant 4 mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rifampicine, Isoniazide, Éthambutol, Pyrazinamide pendant 4 mois et Rifampicine et Isoniazide pendant 2 mois\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Rifampicine, Isoniazide, Éthambutol, Pyrazinamide pendant 3 mois et Rifampicine et Isoniazide pendant 3 mois\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Rifampicine, Isoniazide, Éthambutol, Pyrazinamide pendant 4 mois et Rifampicine et Isoniazide pendant 4 mois\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Rifampicine, Isoniazide, Éthambutol, Pyrazinamide pendant 2 mois et Rifampicine et Isoniazide pendant 4 mois\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le traitement antituberculeux associe 4 antibiotiques (RHZE) pendant 2 mois, puis 2 (RH) pendant 4 mois.\\n\\nSource : Documents de révision L3 Médecine, Tuberculose, QCD 22\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__23\",\n       \"num\": \"24\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Cas pratique : Vous êtes en service au CSU d'Aniassué et vous recevez Mlle Motiky, âgée de 32 ans, caissière dans une banque, pour céphalées, fièvre, vertiges, diarrhée, anorexie, insomnie depuis deux jours. À l'examen vous notez : T° 40 °C, pouls 70 puls/min, TA 120/70 mmHg, poids 90 kg, taille 1,70 m.\",\n       \"text\": \"L'indice de masse corporelle de Mlle Motiky est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"30,14\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"28,14\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"20,14\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 30,14\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"IMC = poids / taille² = 90 / (1,70 × 1,70) = 90 / 2,89 = 31,14.\\n\\nSource : Calcul de l'IMC\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__24\",\n       \"num\": \"25\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Cas pratique : Vous êtes en service au CSU d'Aniassué et vous recevez Mlle Motiky, âgée de 32 ans, caissière dans une banque, pour céphalées, fièvre, vertiges, diarrhée, anorexie, insomnie depuis deux jours. À l'examen vous notez : T° 40 °C, pouls 70 puls/min, TA 120/70 mmHg, poids 90 kg, taille 1,70 m.\",\n       \"text\": \"Mlle Motiky est-elle :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Obèse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Corpulente\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Maigre\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Obèse\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Un IMC ≥ 30 correspond à une obésité (classification OMS).\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__25\",\n       \"num\": \"26\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Cas pratique : Vous êtes en service au CSU d'Aniassué et vous recevez Mlle Motiky, âgée de 32 ans, caissière dans une banque, pour céphalées, fièvre, vertiges, diarrhée, anorexie, insomnie depuis deux jours. À l'examen vous notez : T° 40 °C, pouls 70 puls/min, TA 120/70 mmHg, poids 90 kg, taille 1,70 m.\",\n       \"text\": \"La NFS demandée montre un taux d'hémoglobine à 6 g/dl. Le médecin vous demande de lui faire une transfusion de sang de 420 cc en 3 h 30 min. Quel doit être le débit de cette transfusion ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"30 gouttes/min\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"29 gouttes/min\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"31 gouttes/min\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 30 gouttes/min\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Débit = 420 ml × 15 gouttes / 210 min = 30 gouttes/min (pour le sang, 1 ml = 15 gouttes).\\n\\nSource : Documents de révision L3 Médecine, Transfusion sanguine, QCM 8 et 19 (1 ml de sang = 15 gouttes)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__26\",\n       \"num\": \"27\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un diabète peut être dû à une prédisposition génétique et à des facteurs environnementaux comme l'alimentation\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le diabète résulte d'une prédisposition génétique associée à des facteurs d'environnement (alimentation, sédentarité, obésité).\\n\\nSource : Documents de révision L3 Médecine, Diabète (facteurs de risque des maladies non transmissibles)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__27\",\n       \"num\": \"28\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'hypophyse est contrôlée principalement par l'hypothalamus\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'hypothalamus contrôle l'hypophyse par des hormones de libération (axe hypothalamo-hypophysaire).\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__28\",\n       \"num\": \"29\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les coronaropathies sont aussi appelées cardiopathies ischémiques\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les coronaropathies (angor, infarctus) sont des cardiopathies ischémiques : insuffisance d'apport en oxygène au myocarde par atteinte des artères coronaires.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Insuffisance coronaire : angor, IDM\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__29\",\n       \"num\": \"30\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans l'angine de poitrine, lorsque la douleur persiste en l'absence d'activité physique, on parle d'angor d'effort\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Une douleur survenant en l'absence d'activité physique correspond à l'angor de repos (angor instable) ; l'angor d'effort survient à l'effort et cède à son arrêt.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Angine de poitrine, § 5.1\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__30\",\n       \"num\": \"31\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La douleur de l'angor est de siège thoracique antérieur et rétrosternal\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours décrit la douleur de l'angor comme thoracique antérieure, médiane, rétrosternale en barre.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Angine de poitrine, § 5.2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__31\",\n       \"num\": \"32\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le test diagnostique de l'angor est la trinitrine en sublingual\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"« La douleur cesse après une prise par voie sublinguale de trinitrine en 1 à 2 minutes : c'est un test diagnostique à la trinitrine. »\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Angine de poitrine, § 5.6\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__32\",\n       \"num\": \"33\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la démarche de soins, l'analyse consiste en la classification des données en données d'indépendance et données indépendantes\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'analyse consiste à classer les données en données d'indépendance et données de dépendance (et non « données indépendantes »).\\n\\nSource : Documents de révision L3 Médecine, Soins infirmiers, QCD 1\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__33\",\n       \"num\": \"34\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le rôle de l'infirmier dans l'hépatite virale repose sur l'accueil, les soins, la surveillance du malade, la prophylaxie et la préinscription\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours dit : « le rôle de l'infirmier dans l'hépatite virale repose sur l'accueil, les soins, la surveillance du malade, la prophylaxie et la prévention » ; « préinscription » est faux.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Rôle de l'infirmier dans les hépatites virales\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__34\",\n       \"num\": \"35\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les virus des hépatites B et C sont les causes les plus fréquentes d'hépatite aiguë\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les causes les plus fréquentes d'hépatite aiguë sont les infections virales et les médicaments ; les virus B et C sont cités comme causes les plus fréquentes d'hépatite chronique.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Hépatites, § I-A Causes\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__35\",\n       \"num\": \"36\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La néphropathie gravidique vraie apparaît dans n'importe quelle grossesse ; par contre, la néphropathie gravidique ajoutée ne survient que chez la femme primipare et guérit sans séquelle\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"C'est la néphropathie gravidique vraie qui survient électivement chez la primipare, au 3e trimestre, et guérit sans séquelles. L'énoncé inverse les deux formes.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Néphropathie gravidique vraie\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__36\",\n       \"num\": \"37\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La lithiase urinaire est une complication de la lithiase biliaire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La lithiase urinaire (voies urinaires) et la lithiase biliaire (voies biliaires) sont deux affections distinctes ; l'une n'est pas une complication de l'autre.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__37\",\n       \"num\": \"38\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ponction d'ascite est un acte qui comporte beaucoup d'accidents qu'il faut éviter en surveillant le malade pendant et après la ponction\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"« La ponction d'ascite est un acte qui comporte beaucoup d'accidents qu'il faut éviter en surveillant le malade pendant et après la ponction. »\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Ponction d'ascite, § VII Accidents\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__38\",\n       \"num\": \"39\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le syndrome œdémato-ascitique est l'accident évolutif le plus fréquent de la cirrhose\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"« Le syndrome œdémato-ascitique est l'accident évolutif le plus fréquent de la cirrhose. »\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Les cirrhoses\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__39\",\n       \"num\": \"40\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le collapsus cardio-vasculaire est l'un des accidents de la ponction d'ascite.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Une décompression trop brusque peut entraîner un collapsus cardiovasculaire, cité parmi les accidents de la ponction d'ascite.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Ponction d'ascite, § IV et VII\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__40\",\n       \"num\": \"41\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'insuffisance rénale chronique (IRC) ou insuffisance rénale terminale est une détérioration progressive et réversible de la fonction rénale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'IRC est une détérioration progressive et irréversible de la fonction rénale ; « réversible » rend l'énoncé faux. Remarque : Dans le sujet, il est écrit « déformation rénale » (pour « fonction rénale »).\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Insuffisance rénale chronique, § I\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__41\",\n       \"num\": \"42\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La lithiase urinaire se définit comme la formation de calculs ou précipitation, dans les cavités excrétrices rénales, urétérales ou vésicale, de différents composés organiques\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La lithiase urinaire est la formation de calculs (précipitation de composés) dans les cavités excrétrices : rein, uretère, vessie.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), La lithiase urinaire (explication partiellement hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__42\",\n       \"num\": \"43\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le reflux gastro-œsophagien est la remontée des aliments dans le tube digestif\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours définit le RGO comme la « remontée de liquide gastrique acide dans l'œsophage ». Remarque : La formulation du sujet (« remontée des aliments dans le tube digestif ») est imprécise par rapport à la définition du cours.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Reflux gastro-œsophagien, § 3.2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__43\",\n       \"num\": \"44\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'ulcère gastroduodénal (UGD) se définit comme une perte de substance de la paroi gastrique ou duodénale atteignant en profondeur la musculeuse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"« L'UGD se définit comme une perte de substance de la paroi gastrique ou duodénale atteignant en profondeur la musculeuse. »\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Ulcère gastro-duodénal, § I\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__44\",\n       \"num\": \"45\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le signe capital dans l'ulcère gastro-duodénal est le vomissement\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le signe capital de l'ulcère est la douleur épigastrique (crampe, faim douloureuse, rythmée par les repas, calmée par l'alimentation), pas le vomissement.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Ulcère gastro-duodénal, § III Syndrome ulcéreux typique\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__45\",\n       \"num\": \"46\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La maladie ulcéreuse gastroduodénale est liée à l'infection à Helicobacter pylori.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours cite la « maladie ulcéreuse gastroduodénale liée à l'infection à Helicobacter pylori » parmi les causes principales.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Ulcère gastro-duodénal, § II\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__46\",\n       \"num\": \"47\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le foie intervient dans la régulation de la glycémie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le foie régule la glycémie : il stocke le glucose sous forme de glycogène (glycogénogenèse) et le libère à jeun (glycogénolyse, néoglucogenèse).\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__47\",\n       \"num\": \"48\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La graisse est la principale source d'énergie cellulaire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La principale source d'énergie cellulaire est le glucose ; les graisses sont surtout une réserve d'énergie.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j9-idesfm__48\",\n       \"num\": \"49\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le problème de dépendance et la source de difficulté sont les deux composantes du diagnostic infirmier\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le diagnostic infirmier comporte le problème de dépendance et sa source de difficulté (cause) ; c'est sur la source de difficulté que l'on fonde les interventions. Remarque : La 50e question est coupée dans la capture (dernière page : seul le badge de points apparaît, sans énoncé ni options). Elle n'a pas pu être corrigée.\\n\\nSource : Documents de révision L3 Médecine, Soins infirmiers, QCD 4 et 5\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J9_Medecine_IDE-SF-M_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
